HHAuto_ToolTips.fr['paranoiaSpendsBefore'] = { version: "5.6.24", elementText: "Utiliser points avant", tooltip: "Dépensera des points pour les options (quête, troll, ligues et saison)<br> uniquement si elles sont activées<br>et dépense des points qui seraient perdus pendant la nuit<br> Ex : vous avez la puissance d'un troll à 17, mais en allant 4h45 en paranoïa,<br> cela voudrait dire avoir 17+10 points (arrondis à l'int supérieur), donc être au dessus du 20 max<br> il dépensera alors 8 points pour retomber à 19 fin de la paranoïa, empêchant de perdre des points." };
HHAuto_ToolTips.fr['spendKobans0'] = { version: "8.10.0", elementText: "Dépense Kobans", tooltip: "<p style='color:red'>/!\\ Autorise la dépense des Kobans /!\\</p>Si activé : permet d'activer les fonctions utilisant des kobans" };
HHAuto_ToolTips.fr['kobanBank'] = { version: "5.6.24", elementText: "Kobans à conserver", tooltip: "Minimum de Kobans conservé en banque par les fonctions utilisant des kobans.<br>Ces fonctions ne s'exécuteront pas si elles risquent de faire passer la réserve de kobans sous cette limite." };
HHAuto_ToolTips.fr['buyCombat'] = { version: "8.10.42", elementText: "Acheter comb. pour événement", tooltip: "<p style='color:red'>/!\\ Dépense des Kobans /!\\<br>(" + HHAuto_ToolTips.fr['spendKobans0'].elementText + " doit être activé)</p>Si activé : <br>recharge automatiquement les points de combat durant les X dernières heures de l'événement (sans faire passer sous la valeur de la réserve de Kobans)" };
HHAuto_ToolTips.fr['buyCombTimer'] = { version: "5.6.24", elementText: "Heures d'achat comb.", tooltip: "(Nombre entier)<br>X dernières heures de l'événement" };
HHAuto_ToolTips.fr['autoBuyBoosters'] = { version: "5.6.25", elementText: "Boosters myth. et lég.", tooltip: "<p style='color:red'>/!\\ Fonction dépensant des kobans /!\\<br>(" + HHAuto_ToolTips.fr['spendKobans0'].elementText + " doit être activé)</p>Permet d'acheter des boosters au marché (si cela ne passe pas sous la valeur de la banque de kobans)." };
HHAuto_ToolTips.fr['autoBuyBoostersFilter'] = { version: "8.10.2", elementText: "Boosters à acheter", tooltip: "<span class=\"tipHint\">Une entrée par booster&nbsp;: <code>code:quantité</code>, entrées séparées par <code>;</code></span><p>La quantité est le nombre à garder dans l'inventaire. Les boosters équipés ne comptent pas. <code>0</code> signifie sans limite. Un booster non listé n'est jamais acheté, et un champ vide n'achète rien.</p><p>Valide&nbsp;: <code>MB1:5;MB2:0;MB5:3</code> &mdash; aucun espace.</p><p>Invalide&nbsp;: <code>MB1:5;MB2</code> (pas de quantité), <code>MB1:5;MB1:2</code> (listé deux fois).</p><p><b>Un champ rouge arrête les achats</b> jusqu'à correction. Rien d'autre n'est affecté &mdash; l'équipement continue.</p><ul class=\"tipCodes\"><li><code>B1</code> Ginseng</li><li><code>B2</code> Jujubes</li><li><code>B3</code> Chlorella</li><li><code>B4</code> Cordyceps</li><li><code>MB1</code> Sandalwood perfume</li><li><code>MB2</code> All Mastery's Emblem</li><li><code>MB3</code> Headband of determination</li><li><code>MB4</code> Luxurious Watch</li><li><code>MB5</code> Combative Cinnamon</li><li><code>MB6</code> Alban's travel memories</li><li><code>MB7</code> Angels' semen scent</li><li><code>MB8</code> Leagues mastery emblem</li><li><code>MB9</code> Seasons mastery emblem</li><li><code>MB10</code> Gem Detector</li><li><code>MB11</code> Banger</li><li><code>MB12</code> Shiny Aura</li></ul>" };
