HHAuto_ToolTips.fr['collectAllTimer'] = { version: "8.10.42", elementText: "Minuteur Tout collecter", tooltip: "Nombre d'heure avant la fin de l'evenement pour collecter toutes les récompenses (Faible temps peu entrainer un echec de collecte), Nécéssite une activation sur chaque évenement (POV, POG, season)" };
