HHAuto_ToolTips.fr['plusEventLoveRaidSandalWood'] = { version: "7.25.8", elementText: "Équiper le santal", tooltip: "Équipe le santal avant un combat de Raid amoureux s'il y en a assez dans l'inventaire.<br>N'équipe pas s'il reste moins de 10 fragments à gagner.<br>N'en achète aucun." };
