HHAuto_ToolTips.fr['plusEventSandalWood'] = { version: "7.32.1", elementText: "Équiper le santal", tooltip: "Équipe le santal avant un combat d'événement s'il y en a assez dans l'inventaire.<br>N'équipe pas s'il reste moins de 10 fragments à gagner.<br>N'en achète aucun." };
