HHAuto_ToolTips.de['saveDebug'] = { version: "8.10.0", elementText: "Debug speichern", tooltip: "Erzeugt eine Logdatei, die du an einen Fehlerbericht anhängen kannst." };
HHAuto_ToolTips.de['gitHub'] = { version: "5.6.24", elementText: "GitHub", tooltip: "Link zum GitHub Projekt." };
HHAuto_ToolTips.de['saveConfig'] = { version: "8.10.0", elementText: "Konfig. speichern", tooltip: "Speichert alle Einstellungen in einer Datei." };
HHAuto_ToolTips.de['loadConfig'] = { version: "8.10.0", elementText: "Konfig. laden", tooltip: "Lädt Einstellungen aus einer zuvor gespeicherten Datei." };
HHAuto_ToolTips.de['master'] = { version: "8.10.0", elementText: "Master-Schalter", tooltip: "Schaltet das gesamte Skript an und aus." };
HHAuto_ToolTips.de['autoAdsClick'] = { version: "8.10.42", elementText: "Aktiviert", tooltip: "Klickt die Belohnungswerbung auf der Startseite („Jetzt testen\") automatisch an, schließt den geöffneten Werbe-Tab und bestätigt die Belohnung. Nimmt jede verfügbare Werbung mit. Setzt voraus, dass Werbeblocker aus sind. Läuft mit einer Abklingzeit." };
HHAuto_ToolTips.de['settPerTab'] = { version: "8.10.0", elementText: "Einstellungen pro Tab", tooltip: "Speichert die Einstellungen nur für diesen Browser-Tab statt für alle." };
HHAuto_ToolTips.de['paranoia'] = { version: "8.10.0", elementText: "Paranoia-Modus", tooltip: "Legt Pausen ein, die Schlaf und menschliches Spielverhalten nachahmen." };
HHAuto_ToolTips.de['paranoiaSpendsBefore'] = { version: "8.10.0", elementText: "Gib Punkte aus vor...", tooltip: "<p>An: Punkte werden für Optionen ausgegeben (Quest, Troll, Liga und Saison) &mdash; aber nur für Optionen, die aktiviert sind, und nur Punkte, die über dem Maximum landen würden.</p><p><b>Beispiel:</b> Deine Troll-Power steht auf 17, du gehst für 4h45 in den Paranoia-Modus. Das wären 17+10 Punkte (aufgerundet) und damit über dem Maximum von 20. Es werden dann 9 Punkte ausgegeben, sodass du zum Ende des Paranoia-Modus bei 19 bleibst und nichts verlierst.</p>" };
HHAuto_ToolTips.de['spendKobans0'] = { version: "8.10.0", elementText: "Kobans ausgeben", tooltip: "<p style='color:red'>/!\\ Erlaubt das Ausgeben von Kobans /!\\</p>Sicherheitsschalter für die Koban-Nutzung. Muss aktiv sein, damit überhaupt eine Funktion Kobans ausgeben darf." };
HHAuto_ToolTips.de['kobanBank'] = { version: "8.10.0", elementText: "Koban-Bank", tooltip: "(Ganze Zahl)<br>So viele Kobans werden nie ausgegeben." };
HHAuto_ToolTips.de['buyCombat'] = { version: "8.10.42", elementText: "Kämpfe kaufen (Event)", tooltip: "'Kobans ausgeben'-Funktion<br>Wenn aktiv: kauft Kampfpunkte in den letzten X Stunden eines Events, solange die Koban-Bank nicht unterschritten wird." };
HHAuto_ToolTips.de['buyCombTimer'] = { version: "5.6.24", elementText: "Stunden bis Kauf", tooltip: "(Ganze pos. Zahl)<br>X verbleibende Stunden des Events" };
HHAuto_ToolTips.de['autoBuyBoosters'] = { version: "5.6.25", elementText: "Myth. & leg. Booster", tooltip: "<p style='color:red'>/!\\ Kobans ausgeben /!\\<br>(" + HHAuto_ToolTips.de['spendKobans0'].elementText + " muss AN sein)</p>Erlaubt den Kauf von Boostern im Markt (solange die Koban-Bank nicht unterschritten wird)." };
HHAuto_ToolTips.de['autoBuyBoostersFilter'] = { version: "8.10.2", elementText: "Zu kaufende Booster", tooltip: "<span class=\"tipHint\">Ein Eintrag je Booster: <code>Code:Menge</code>, Einträge durch <code>;</code> getrennt</span><p>Die Menge ist, wie viele davon im Inventar liegen sollen. Angelegte Booster zählen nicht mit. <code>0</code> heißt ohne Begrenzung. Ein nicht genannter Booster wird nie gekauft, ein leeres Feld kauft gar nichts.</p><p>Gültig: <code>MB1:5;MB2:0;MB5:3</code> &mdash; keine Leerzeichen.</p><p>Ungültig: <code>MB1:5;MB2</code> (keine Menge), <code>MB1:5;MB1:2</code> (doppelt genannt).</p><p><b>Ein rotes Feld hält den Kauf an</b>, bis es korrigiert ist. Sonst ändert sich nichts &mdash; das Anlegen läuft weiter.</p><ul class=\"tipCodes\"><li><code>B1</code> Ginseng</li><li><code>B2</code> Jujubes</li><li><code>B3</code> Chlorella</li><li><code>B4</code> Cordyceps</li><li><code>MB1</code> Sandalwood perfume</li><li><code>MB2</code> All Mastery's Emblem</li><li><code>MB3</code> Headband of determination</li><li><code>MB4</code> Luxurious Watch</li><li><code>MB5</code> Combative Cinnamon</li><li><code>MB6</code> Alban's travel memories</li><li><code>MB7</code> Angels' semen scent</li><li><code>MB8</code> Leagues mastery emblem</li><li><code>MB9</code> Seasons mastery emblem</li><li><code>MB10</code> Gem Detector</li><li><code>MB11</code> Banger</li><li><code>MB12</code> Shiny Aura</li></ul>" };
HHAuto_ToolTips.de['autoSeasonPassReds'] = { version: "8.10.0", elementText: "Überspringe drei Rote", tooltip: "'Koban ausgeben Funktion'<br>Benutze Kobans um Saison Gegner zu tauschen wenn alle drei Rote sind" };
HHAuto_ToolTips.de['showCalculatePower'] = { version: "8.10.0", elementText: "PowerCalc", tooltip: "Zeigt den Kampfsimulator bei Liga, Kampf und Saison an." };
HHAuto_ToolTips.de['showInfo'] = { version: "8.10.43", elementText: "Aktiviert", tooltip: "Wenn aktiv : zeige Information auf Skriptwerten und nächsten Durchläufen" };
HHAuto_ToolTips.de['autoSalary'] = { version: "8.10.42", elementText: "Einsammeln", tooltip: "Wenn aktiv :<br>Sammelt das gesamte Einkommen alle X Sek." };
HHAuto_ToolTips.de['autoMission'] = { version: "8.10.42", elementText: "Aktiviert", tooltip: "Wenn aktiv : Macht automatisch Missionen" };
HHAuto_ToolTips.de['autoMissionCollect'] = { version: "5.6.24", elementText: "Einsammeln", tooltip: "Wenn aktiv : Sammelt automatisch Missionsgewinne" };
HHAuto_ToolTips.de['autoTrollBattle'] = { version: "8.10.42", elementText: "Aktiviert", tooltip: "Wenn aktiv: Macht automatisch Kämpfe gegen den Standard-Troll" };
HHAuto_ToolTips.de['autoTrollSelector'] = { version: "8.10.0", elementText: "Troll-Auswahl", tooltip: "Wähle den Troll, gegen den gekämpft werden soll." };
HHAuto_ToolTips.de['autoTrollThreshold'] = { version: "5.6.24", elementText: "Schwellwert", tooltip: "Minimum an Trollpunkten die aufgehoben werden" };
HHAuto_ToolTips.de['eventTrollOrder'] = { version: "8.10.36", elementText: "Reihenfolge der Event-Trolle", tooltip: "<span class=\"tipHint\">Werte durch ; getrennt &mdash; die Reihenfolge wird eingehalten.</span><p>Die Reihenfolge, in der Event-Trolle automatisch bekämpft werden.</p><ul class=\"tipCodes\"><li><code>1</code> Dark Lord</li><li><code>2</code> Ninja Spy</li><li><code>3</code> Gruntt</li><li><code>4</code> Edwarda</li><li><code>5</code> Donatien</li><li><code>6</code> Silvanus</li><li><code>7</code> Bremen</li><li><code>8</code> Finalmecia</li><li><code>9</code> Roko Sensei</li><li><code>10</code> Karole</li><li><code>11</code> Jackson's Crew</li><li><code>12</code> Pandora witch</li><li><code>13</code> Nike</li><li><code>14</code> Sake</li><li><code>15</code> WereBunny Police</li><li><code>16</code> Auga</li><li><code>17</code> Gross</li><li><code>18</code> Harriet</li><li><code>19</code> Darth Excitor</li><li><code>22</code> Daddy</li></ul><p>Die Nummern 20 und 21 sind Trolle der Nebenabenteuer und haben keinen Namen.</p>" };
HHAuto_ToolTips.de['plusEvent'] = { version: "8.10.42", elementText: "Aktiviert", tooltip: "Kämpft gegen normale Event-Trolle unabhängig von Auto-Troll.<br>Die Energie-Schwelle wird beachtet." };
HHAuto_ToolTips.de['plusEventMythic'] = { version: "8.10.42", elementText: "Aktiviert", tooltip: "Kämpft gegen Mythic-Event-Trolle unabhängig von Auto-Troll.<br>Übergeht die Energie-Schwelle. Hat Vorrang vor normalen Events." };
HHAuto_ToolTips.de['raidStarsSelector'] = { version: "8.10.0", elementText: "+Liebesüberfall-Sterne", tooltip: "<p>Kämpfe Liebesüberfälle nach Mädchen-Grad. Unabhängig von <b>+Liebesüberfall</b> und <b>Auto Troll</b>.</p><ul><li>Wählt automatisch den als nächstes endenden Liebesüberfall mit passendem Grad (ignoriert das Auswahl-Dropdown).</li><li>Passende Liebesüberfälle werden von <b>+Liebesüberfall-Sterne</b> beansprucht; übrige gehen an <b>+Liebesüberfall</b>, falls aktiv.</li><li>Die Energie-Schwelle steuert der Schalter <b>Reserve umgehen</b>.</li></ul>" };
HHAuto_ToolTips.de['raidStarsOff'] = { version: "7.35.5", elementText: "Aus" };
HHAuto_ToolTips.de['autoEquipMythicBooster'] = { version: "8.10.0", elementText: "Mythic-Slot", tooltip: "<span class=\"tipHint\">Codes durch ; getrennt &mdash; so viele wie du willst.</span><p>Mythische Booster, die angelegt bleiben sollen, <b>in der Reihenfolge deiner Priorität</b>. Das Spiel hat <b>5 mythische Slots</b> (ein Booster je Art), es sind also höchstens 5 gleichzeitig an. Das Skript geht die Liste von oben durch und füllt jeden freien Slot mit den ersten, die du besitzt.</p><p>Alle 12 einzutragen ist sinnvoll und genau der Zweck: es heißt <i>nimm davon, was ich gerade habe</i>. Leeres Feld schaltet es aus.<br>Beispiel: <code>MB1;MB2;MB5;MB8;MB12</code></p><p>Es wird nichts gekauft, und ein bereits angelegter Booster wird nie ersetzt.</p><p><b>Sandelholz:</b> Solange eine der Sandelholz-Automatiken (+Event / +Mythisch / +Raid) aktiv ist, gehört MB1 ihr &mdash; es wird hier ignoriert, auch wenn du es einträgst, und ein Slot bleibt frei. Deine Liste füllt dann höchstens 4 der 5. Das sichert zu, dass ein Slot verfügbar ist, wenn Sandelholz gebraucht wird, und dass vor dem Kampf geprüft wird, ob es angelegt ist. Sind alle diese Optionen aus, ist MB1 ein normaler Eintrag und die Liste bekommt alle fünf Slots.</p>" };
HHAuto_ToolTips.de['raidStarsExact3'] = { version: "7.35.5", elementText: "=3 ★★★" };
