HHAuto_ToolTips.es['plusEventLoveRaidSandalWood'] = { version: "7.25.8", elementText: "Equipar sándalo", tooltip: "Equipa el sándalo antes de un combate de Incursión de Amor si hay suficiente en el inventario.<br>No lo equipa si faltan menos de 10 fragmentos.<br>No compra ninguno." };
