HHAuto_ToolTips.es['loveRaidTitle'] = { version: "7.25.5", elementText: "Incursión de Amor", tooltip: "" };
HHAuto_ToolTips.es['plusEventSandalWood'] = { version: "7.32.1", elementText: "Equipar sándalo", tooltip: "Equipa el sándalo antes de un combate de evento si hay suficiente en el inventario.<br>No lo equipa si faltan menos de 10 fragmentos.<br>No compra ninguno." };
HHAuto_ToolTips.es['plusEventMythicSandalWood'] = { version: "7.2.0", elementText: "Equipar sándalo", tooltip: "Equipa el sándalo antes de un combate mítico si hay suficiente en el inventario.<br>No lo equipa si faltan menos de 10 fragmentos.<br>No compra ninguno." };
