;// ./src/Helper/TimeHelper.ts
// TimeHelper.ts
//
// Time-related utilities: converting between human-readable durations
// ("2d 05:30:00"), seconds, and the game's localized timer strings
// (e.g. "2j 5h 30m" in French). Also provides contest-safe-time
// logic that prevents spending energy too close to a contest end.
//
// The game renders timers with locale-specific unit labels (h/m/s in
// English, j/h/m/s in French, etc.). convertTimeToInt() uses the
// i18n timer definitions to parse these back into seconds regardless
// of locale.
//
// Used by: TimerHelper (set/check cooldowns), AutoLoop (scheduling),
//          InfoService (display remaining times)






class TimeHelper {
    static getContestSafeTime() {
        if (getStoredValue(HHStoredVarPrefixKey + SK.waitforContest) !== "true") {
            return 0;
        }
        const safeTimeStr = getStoredValue(HHStoredVarPrefixKey + SK.safeSecondsForContest);
        let safeTime = safeTimeStr !== undefined ? Number(safeTimeStr) : 120;
        if (isNaN(safeTime) || safeTime < 0)
            safeTime = 120;
        return safeTime;
    }
    static canCollectCompetitionActive() {
        const safeTime = TimeHelper.getContestSafeTime();
        return getStoredValue(HHStoredVarPrefixKey + SK.waitforContest) !== "true" || !((getSecondsLeft('contestRemainingTime') - safeTime) < 0 && getSecondsLeft('nextContestTime') > 0);
    }
    static toHHMMSS(secs) {
        var sec_num = parseInt(secs, 10);
        var days = Math.floor(sec_num / 86400);
        var hours = Math.floor(sec_num / 3600) % 24;
        var minutes = Math.floor(sec_num / 60) % 60;
        var seconds = sec_num % 60;
        var n = 0;
        return [days, hours, minutes, seconds]
            .map(v => v < 10 ? "0" + v : v)
            .filter((v, i) => { if (v !== "00") {
            n++;
            return true;
        } return n > 0; })
            .join(":");
    }
    static debugDate(sec_num) {
        const days = Math.floor(sec_num / 86400);
        const hours = Math.floor(sec_num / 3600) % 24;
        const minutes = Math.floor(sec_num / 60) % 60;
        const seconds = sec_num % 60;
        return JSON.stringify({ days: days, hours: hours, minutes: minutes, seconds: seconds });
    }
    /**
     * Pauses execution for a specified duration.
     * @param waitTime - The number of milliseconds to sleep.
     * @returns A promise that resolves after the specified wait time.
     */
    static sleep(waitTime) {
        return new Promise((resolve) => {
            setTimeout(resolve, waitTime);
        });
    }
}
function convertTimeToInt(remainingTimer, failSafe = true) {
    let newTimer = 0;
    if (remainingTimer && remainingTimer.length > 0) {
        try {
            const splittedTime = remainingTimer.trim().split(' ');
            for (let i = 0; i < splittedTime.length; i++) {
                const timerSymbol = splittedTime[i].match(/[^0-9]+/)[0];
                switch (timerSymbol) {
                    case timerDefinitions[hhTimerLocale].days:
                        newTimer += parseInt(splittedTime[i]) * 86400;
                        break;
                    case timerDefinitions[hhTimerLocale].hours:
                        newTimer += parseInt(splittedTime[i]) * 3600;
                        break;
                    case timerDefinitions[hhTimerLocale].minutes:
                        newTimer += parseInt(splittedTime[i]) * 60;
                        break;
                    case timerDefinitions[hhTimerLocale].seconds:
                        newTimer += parseInt(splittedTime[i]);
                        break;
                    default:
                        logHHAuto('Timer symbol not recognized: ' + timerSymbol);
                }
            }
        }
        catch ({ errName, message }) {
            if (failSafe) {
                logHHAuto(`ERROR: occured, reset to 15min: ${errName}, ${message}`);
                newTimer = randomInterval(15 * 60, 17 * 60);
            }
            else {
                logHHAuto(`ERROR: occured, return -1: ${errName}, ${message}`);
                newTimer = -1;
            }
        }
    }
    else {
        if (failSafe) {
            logHHAuto('No valid timer definitions, reset to 15min');
            newTimer = randomInterval(15 * 60, 17 * 60);
        }
        else {
            logHHAuto('No valid timer definitions, return -1');
            newTimer = -1;
        }
    }
    return newTimer;
}
function getLimitTimeBeforeEnd() {
    return Number(getStoredValue(HHStoredVarPrefixKey + SK.collectAllTimer)) * 3600;
}
function randomInterval(min, max) {
    return Math.floor(Math.random() * (max - min + 1) + min);
}

;// ./src/Helper/TimerHelper.ts
// TimerHelper.ts
//
// Manages named cooldown timers that prevent actions from running too
// frequently. Each timer is stored as a future timestamp (epoch ms)
// in the in-memory `Timers` object (persisted to storage as JSON).
//
// The AutoLoop checks timers before each action: e.g. "nextLeaguesTime"
// prevents league fights until energy regenerates. When a module
// performs an action, it calls setTimer("name", seconds) to schedule
// the next allowed run.
//
// Two check modes:
//   - checkTimer: returns true if timer is missing OR expired (safe default)
//   - checkTimerMustExist: returns true only if timer exists AND expired
//     (used when absence means "not yet initialized", not "ready")
//
// Used by: Every module (via AutoLoop), StartService (timer restoration)





let Timers = {};
function setTimers(timer) {
    Timers = timer;
}
function setTimer(name, seconds) {
    var ND = new Date().getTime() + seconds * 1000;
    Timers[name] = ND;
    setStoredValue(HHStoredVarPrefixKey + TK.Timers, JSON.stringify(Timers));
    logHHAuto(name + " set to " + TimeHelper.toHHMMSS(ND / 1000 - new Date().getTimezoneOffset() * 60) + ' (' + TimeHelper.toHHMMSS(seconds) + ')');
}
function clearTimer(name) {
    delete Timers[name];
    setStoredValue(HHStoredVarPrefixKey + TK.Timers, JSON.stringify(Timers));
}
function checkTimer(name) {
    if (!Timers[name] || Timers[name] < new Date()) {
        return true;
    }
    return false;
}
function checkTimerMustExist(name) {
    if (Timers[name] && Timers[name] < new Date()) {
        return true;
    }
    return false;
}
function getTimer(name) {
    if (!Timers[name]) {
        return -1;
    }
    return Timers[name];
}
function getSecondsLeft(name) {
    if (!Timers[name]) {
        return 0;
    }
    var result = Math.ceil(Timers[name] / 1000) - Math.ceil(new Date().getTime() / 1000);
    if (result > 0) {
        return result;
    }
    else {
        return 0;
    }
}
function getTimeLeft(name) {
    const timerWaitingCompet = ['nextPachinkoTime', 'nextPachinko2Time', 'nextPachinkoEquipTime', 'nextSeasonTime', 'nextLeaguesTime', 'nextChampionTime', 'nextClubChampionTime', 'nextLabyrinthTime', 'nextPentaDrillTime', 'nextPantheonTime'];
    if (!Timers[name]) {
        if (!TimeHelper.canCollectCompetitionActive() && timerWaitingCompet.indexOf(name) >= 0) {
            return "Wait for contest";
        }
        return "No timer";
    }
    var diff = getSecondsLeft(name);
    if (diff <= 0) {
        if (!TimeHelper.canCollectCompetitionActive() && timerWaitingCompet.indexOf(name) >= 0) {
            return "Wait for contest";
        }
        return "Time's up!";
    }
    return TimeHelper.toHHMMSS(diff);
}

